const items = $input.all();
const config = $('Config').item.json;
const minDelta = Number(config.minPriceDelta) || 50;
const results = [];

for (const item of items) {
  const data = item.json;

  // Skip if API returned an error or missing product
  if (data.detail && !data.product_id) continue;

  const productId = data.product_id || 'Unknown';

  // Attempt to recover product name from previous node or history
  let productName = data.product_name;
  if (!productName) {
    try {
      const splitItems = $('Split Each Product').all();
      const matched = splitItems.find(p => p.json && p.json.product_id === productId);
      if (matched && matched.json.product_name) {
        productName = matched.json.product_name;
      }
    } catch (e) {
      // fallback
    }
  }
  productName = productName || 'Monitored Product';

  const currentPrice = Number(data.latest_observed_price ?? data.discounted_price ?? 0);
  const originalPrice = Number(data.first_observed_price ?? data.actual_price ?? currentPrice);
  const changeAmount = Number(data.price_change_amount ?? (currentPrice - originalPrice));
  const changePct = Number(data.price_change_percentage ?? (originalPrice > 0 ? ((changeAmount / originalPrice) * 100) : 0));
  const isAllTimeLow = Boolean(data.is_at_all_time_low);

  const absChange = Math.abs(changeAmount);
  const isDrop = changeAmount <= -minDelta;
  const isIncrease = changeAmount >= minDelta;

  if (isDrop || isIncrease) {
    const formattedCurrent = '₹' + currentPrice.toLocaleString('en-IN');
    const formattedOriginal = '₹' + originalPrice.toLocaleString('en-IN');
    const formattedDelta = '₹' + absChange.toLocaleString('en-IN');
    const pctString = Math.abs(changePct).toFixed(1) + '%';

    let header = '';
    let changeLine = '';
    if (isDrop) {
      header = '🟢 <b>PRICE DROP ALERT!</b>';
      changeLine = `🎉 <b>You Save:</b> ${formattedDelta} (-${pctString})`;
      if (isAllTimeLow) {
        header += ' 🔥 <i>ALL-TIME LOW!</i>';
      }
    } else {
      header = '🔴 <b>PRICE INCREASE NOTICE!</b>';
      changeLine = `📈 <b>Increased By:</b> +${formattedDelta} (+${pctString})`;
    }

    const message = [
      header,
      '',
      `📦 <b>${productName}</b>`,
      `💰 <b>New Price:</b> <code>${formattedCurrent}</code>`,
      `<s>Original Price: ${formattedOriginal}</s>`,
      changeLine,
      '',
      `🆔 <b>Product ID:</b> <code>${productId}</code>`,
      `⏰ <b>Updated:</b> ${new Date().toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}`,
      `⚡ <i>Automated by ReviewPulse Neural Engine</i>`
    ].join('\n');

    results.push({
      json: {
        should_alert: true,
        productId,
        productName,
        currentPrice,
        originalPrice,
        changeAmount,
        changePct,
        type: isDrop ? 'PRICE_DROP' : 'PRICE_INCREASE',
        message
      }
    });
  } else {
    results.push({
      json: {
        should_alert: false,
        productId,
        productName,
        reason: 'Change below threshold (' + absChange + ' < ' + minDelta + ')'
      }
    });
  }
}

return results;
